    ball: { x: 100, y: 85, r: 7, vx: 0, vy: 100 },
    bricks: [{ x: 90, y: 90, w: 20, h: 20, alive: true, points: 10 }],
    score: 0,
    combo: 0,
    level: 1
  };
  resolveBricks(state, 0.01);
  assert.ok(state.ball.vy < 0, 'should bounce up');
  assert.ok(state.ball.y < 90 - 7, 'should be pushed out');
});

test('resolveBricks: bottom bounce', () => {
  const state = {
    ball: { x: 100, y: 105, r: 7, vx: 0, vy: -100 },
    bricks: [{ x: 90, y: 90, w: 20, h: 20, alive: true, points: 10 }],
    score: 0,
    combo: 0,
    level: 1
  };
  resolveBricks(state, 0.01);
  assert.ok(state.ball.vy > 0, 'should bounce down');
  assert.ok(state.ball.y > 110 + 7, 'should be pushed out');
});

test('resolveBricks: left bounce', () => {
  const state = {
    ball: { x: 85, y: 100, r: 7, vx: 100, vy: 0 },
    bricks: [{ x: 90, y: 90, w: 20, h: 20, alive: true, points: 10 }],
    score: 0,
    combo: 0,
    level: 1
  };
  resolveBricks(state, 0.01);
  assert.ok(state.ball.vx < 0, 'should bounce left');
  assert.ok(state.ball.x < 90 - 7, 'should be pushed out');
});

test('resolveBricks: right bounce', () => {
  const state = {
    ball: { x: 115, y: 100, r: 7, vx: -100, vy: 0 },
    bricks: [{ x: 90, y: 90, w: 20, h: 20, alive: true, points: 10 }],
    score: 0,
    combo: 0,
    level: 1
  };
  resolveBricks(state, 0.01);
  assert.ok(state.ball.vx > 0, 'should bounce right');
  assert.ok(state.ball.x > 110 + 7, 'should be pushed out');
});

test('resolveBricks: corner bounce', () => {
  const state = {
    ball: { x: 88, y: 88, r: 7, vx: 100, vy: 100 },
    bricks: [{ x: 90, y: 90, w: 20, h: 20, alive: true, points: 10 }],
    score: 0,
    combo: 0,
    level: 1
  };
  resolveBricks(state, 0.01);
  assert.ok(state.ball.vx < 0 && state.ball.vy < 0, 'should bounce back diagonally');
});

test('resolveBricks: tunnelling (sweep)', () => {
  const state = {
    ball: { x: 100, y: 150, r: 7, vx: 0, vy: -1000 }, // very fast upward
    bricks: [{ x: 90, y: 100, w: 20, h: 20, alive: true, points: 10 }],
    score: 0,
    combo: 0,
    level: 1
  };
  // dt = 0.05 => movement = 50px. Ball starts at 150, ends at 100.
  // Brick is at 100-120. It should hit the bottom of the brick.
  resolveBricks(state, 0.05);
  assert.ok(state.ball.vy > 0, 'should have detected collision during sweep');
});

test('resolveBricks: neighbours (single bounce)', () => {
  const state = {
    ball: { x: 90, y: 100, r: 7, vx: 100, vy: 0 },
    bricks: [
      { x: 90, y: 90, w: 10, h: 20, alive: true, points: 10 },
